const tr=x=>{if(L!=='en')return x;if(EN[x])return EN[x];const m=x.match(/^dostępny[,:] (.+)$/);return m?'available: '+(EN[m[1]]||m[1]):x};
const trSrc=x=>L!=='en'?x:x.replace('adres:','address:').replace('(geokodowanie przybliżone w prototypie)','(approximate geocoding in this prototype)').replace('domyślnie','default').replace('wskazano na mapie','picked on map').replace('centrum:','centre:').replace('nowy AED','new AED');
function saveMe(){try{localStorage.setItem('pz_me',JSON.stringify(me))}catch{}}
try{const m=JSON.parse(localStorage.getItem('pz_me'));if(m&&m.la)me=m}catch{}
function geocode(q){const s=q.trim().toLowerCase();if(!s)return null;const city=Object.keys(CITY).sort((a,b)=>b.length-a.length).find(c=>new RegExp(`(^|[\\s,])${c}($|[\\s,])`).test(s));const base=city?CITY[city]:[me.la,me.lo];
  const st=STREETS.find(x=>s.includes(x.toLowerCase()));if(!city&&!st)return null;let h=0;for(const ch of (st||'')+s)h=(h*31+ch.charCodeAt(0))%9973;const off=st?[(h%100-50)/2500,(Math.floor(h/100)%100-50)/1600]:[0,0];
  return {la:+(base[0]+off[0]).toFixed(6),lo:+(base[1]+off[1]).toFixed(6),src:`adres: ${q.trim()} (geokodowanie przybliżone w prototypie)`}}
let sos={st:'idle'};const AED_MAX=1000;const framed=(()=>{try{return window.top!==window}catch{return true}})();
const gmSearch=q=>`https://www.google.com/maps/dir/?api=1&travelmode=walking&destination=${encodeURIComponent('defibrylator AED')}${q&&q.trim()?`&origin=${encodeURIComponent(q.trim())}`:''}`;const mapsUrl=r=>`https://www.google.com/maps/dir/?api=1&travelmode=walking&destination=${r.lat},${r.lon}`;
function locate(){if(!navigator.geolocation){sos.st='ask';return renderSos()}sos.st='locating';renderSos();
  const ok=p=>{me={la:p.coords.latitude,lo:p.coords.longitude,src:'GPS'};saveMe();sos.st='found';renderSos()};
  const fail=e=>{sos.denied=e&&e.code===1;sos.st='ask';renderSos()};
  navigator.geolocation.getCurrentPosition(ok,e=>e.code===1?fail(e):navigator.geolocation.getCurrentPosition(ok,fail,{enableHighAccuracy:false,timeout:12000,maximumAge:600000}),{enableHighAccuracy:true,timeout:6000,maximumAge:60000})}
document.addEventListener('submit',e=>{if(e.target.id!=='locForm')return;e.preventDefault();const g=geocode($('#addr').value);if(!g){location.href=gmSearch($('#addr').value);return}me=g;saveMe();sos.st='found';renderSos()});
document.addEventListener('click',e=>{const t=e.target.closest('[data-sos]');if(!t)return;
  if(t.dataset.sos==='demo'){const v=live(AED).find(r=>r.status_rekordu==='zweryfikowany'&&r.calodobowo==='true'&&r.sposob_otwarcia==='swobodny'&&r.miejscowosc==='Bydgoszcz');me={la:v.lat+.002,lo:v.lon+.002,src:'demo'};sos.st='found';renderSos()}
  if(t.dataset.sos==='find'){if(sos.denied)location.href=gmSearch('');else locate()}
  if(t.dataset.sos==='again'){sos.st='ask';renderSos();$('#addr')?.focus()}});
const barrier=r=>({kod_od_dyspozytora:T[L].b_code,klucz_u_pracownika:T[L].b_key,pomoc_pracownika:T[L].b_staff})[r.sposob_otwarcia]||'';
function renderSos(){const box=$('#sosMain');if(!box)return;
  if(sos.st==='idle'){if(!$('#v-ratunek').classList.contains('on'))return;return locate()}
  if(sos.st==='locating'){box.innerHTML=`<div class="wait"><span class="spin" aria-hidden="true"></span>${T[L].locating}</div>`;return}
  if(sos.st==='ask'){box.innerHTML=`<div class="askbig"><button type="button" data-sos="find" class="big green" style="min-height:150px;width:100%;font-size:clamp(30px,8vw,44px)">${T[L].openMap}</button><form id="locForm" role="search" style="display:grid;gap:8px"><label for="addr" style="font-size:18px;font-weight:700">${T[L].orAddr}</label><div class="row" style="flex-wrap:nowrap"><input type="text" id="addr" autocomplete="street-address" enterkeyhint="go" placeholder="${T[L].ph}"><button type="submit" class="go2" style="min-height:56px;font-size:18px;flex:none" aria-label="${T[L].find}">${ic('nav')}</button></div></form>${framed?`<button type="button" data-sos="demo" style="font-size:15px;min-height:44px">${T[L].demo}</button>`:''}</div>`;return}
  const now=new Date();const best=live(AED).filter(r=>r.status_rekordu==='zweryfikowany').map(r=>({r,s:state(r,now),d:dist(me,{la:r.lat,lo:r.lon})})).filter(o=>o.s[0]!=='off').sort((a,b)=>a.d-b.d)[0];
  if(!best||best.d>AED_MAX){uczFar=best||null;box.innerHTML=`<a class="big red" href="#uciskaj" style="background:light-dark(#1a1d2e,#2c2f38);font-size:clamp(34px,9vw,52px)">${T[L].press}<span class="sub">${T[L].press_s}</span></a>`;return}
  const r=best.r,b=barrier(r);
  box.innerHTML=`<a class="big green" href="#prowadz-${r.id_aed}">AED<span style="font-size:clamp(40px,12vw,64px)">${fmtD(best.d)} →</span><span class="sub">${esc(r.nazwa_obiektu)}${b?` · ${b}`:''}</span></a>`}
let uczFar=null,uczStart=0,uczT=null,uczSnd=false,uczCtx=null;
function uczOpen(){uczStart=Date.now();clearInterval(uczT);let on=false;
  uczT=setInterval(()=>{on=!on;const p=$('#press');if(!p||!$('#v-uciskaj').classList.contains('on')){clearInterval(uczT);return}p.classList.toggle('on',on);
    if(on&&uczSnd&&uczCtx){const o=uczCtx.createOscillator(),g=uczCtx.createGain();o.frequency.value=880;g.gain.value=.2;o.connect(g).connect(uczCtx.destination);o.start();o.stop(uczCtx.currentTime+.05)}
    const s=Math.floor((Date.now()-uczStart)/1000);$('#uczT').textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`},60000/110/2);
  const addr=me.src&&me.src.startsWith('adres:')?me.src.replace(/^adres: /,'').replace(/ \(.*\)$/,''):'';
  $('#sayWhere').textContent=addr||`${me.la.toFixed(5)}, ${me.lo.toFixed(5)}`;$('#sayExtra').textContent=addr?'':T[L].coords+' (GPS)';
  const far=uczFar||live(AED).filter(r=>r.status_rekordu==='zweryfikowany').map(r=>({r,d:dist(me,{la:r.lat,lo:r.lon})})).sort((a,b)=>a.d-b.d)[0];
  $('#uczAed').innerHTML=far&&far.d<2000?`<div class="say"><span class="note">${T[L].runner.replace('{d}',fmtD(far.d))}</span><div class="row" style="margin-top:10px"><button class="okb" id="uczSend">${ic('nav')} ${T[L].send}</button></div></div>`:'';
  $('#uczSend')&&($('#uczSend').onclick=e=>copy(`Pilne: potrzebny AED. Biegnij tutaj: ${mapsUrl(far.r)} i przynieś go do: ${addr||me.la.toFixed(5)+', '+me.lo.toFixed(5)}`,e.target,T[L].copied))}
document.addEventListener('click',e=>{if(e.target.closest('#uczSound')){uczSnd=!uczSnd;try{uczCtx=uczCtx||new (window.AudioContext||window.webkitAudioContext)()}catch{}e.target.closest('#uczSound').textContent=uczSnd?T[L].ucz_sound_off:T[L].ucz_sound}});
let metro=null,actx=null;$('#metroBtn').onclick=e=>{if(metro){clearInterval(metro);metro=null;e.target.textContent=T[L].metro;$('#beat').classList.remove('on');return}
  try{actx=actx||new (window.AudioContext||window.webkitAudioContext)()}catch{}e.target.textContent=T[L].metro_off;let on=false;
  metro=setInterval(()=>{on=!on;$('#beat').classList.toggle('on',on);if(on&&actx){const o=actx.createOscillator(),g=actx.createGain();o.frequency.value=880;g.gain.value=.15;o.connect(g).connect(actx.destination);o.start();o.stop(actx.currentTime+.05)}},60000/110/2)};

let repPos=null,repImg=null,repFile=null,repGps=null,repWatch=null,repFix=null;
const API='/api';
const devId=()=>{try{let d=localStorage.getItem('aed_dev');if(!d){d=crypto.randomUUID();localStorage.setItem('aed_dev',d)}return d}catch{return 'anon'}};
function repGpsStart(){if(repWatch!==null||!navigator.geolocation){if(!navigator.geolocation)$('#r_gps').textContent='Ta przeglądarka nie udostępnia lokalizacji.';return}
  repWatch=navigator.geolocation.watchPosition(p=>{const f={la:p.coords.latitude,lo:p.coords.longitude,acc:p.coords.accuracy,ts:p.timestamp};if(!repFix||f.acc<=repFix.acc||f.ts-repFix.ts>15000)repFix=f;
    if(!repFile)$('#r_gps').textContent=repFix.acc<=50?`Lokalizacja gotowa (±${Math.round(repFix.acc)} m)`:`Słaby sygnał GPS (±${Math.round(repFix.acc)} m) – podejdź do okna lub wyjdź na zewnątrz`},
  er=>{$('#r_gps').textContent=er.code===1?'Brak zgody na lokalizację. Zezwól na nią w ustawieniach strony – bez niej nie przyjmiemy zgłoszenia.':'Nie udało się ustalić lokalizacji.'},{enableHighAccuracy:true,maximumAge:0,timeout:30000})}
