  const raw={nazwa_obiektu:$('#r_nazwa').value||'AED',miejscowosc:$('#r_miasto').value,kod_pocztowy:$('#r_kod').value,ulica:$('#r_ulica').value,numer_budynku:$('#r_nr').value,lat:repPos.la,lon:repPos.lo,opis_dojscia:$('#r_opis').value,calodobowo:tryb==='24/7'?'true':'',godziny_dostepu:tryb==='godziny'?godz:'',kategoria_dostepu:$('#r_kat').value,stacjonarny:'true',umiejscowienie:'inne',sposob_otwarcia:'nieznany',status_sprawnosci:'nieznany',zrodlo:'zgloszenie_mieszkanca',sposob_weryfikacji:'zdjecie',status_rekordu:'zgloszony'};
