$('#delCheck').onclick=()=>{const r=AED.find(a=>a.id_aed===delId);r.status_rekordu='wymaga_sprawdzenia';$('#dlgDel').close();drawQueue()};$('#delX').onclick=()=>$('#dlgDel').close();

